import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.Dbgp30TS.js";const g=JSON.parse('{"title":"教程 07 · React Native 0.87 更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/07-changelog.md","filePath":"tutorial/07-changelog.md","lastUpdated":1790521026000}'),i={name:"tutorial/07-changelog.md"};function s(r,e,n,c,l,p){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="教程-07-·-react-native-0-87-更新日志" tabindex="-1">教程 07 · React Native 0.87 更新日志 <a class="header-anchor" href="#教程-07-·-react-native-0-87-更新日志" aria-label="Permalink to &quot;教程 07 · React Native 0.87 更新日志&quot;">​</a></h1><blockquote><p>本章基于官方发布公告（<a href="https://reactnative.dev/blog/2026/08/11/react-native-0.87" target="_blank" rel="noreferrer">React Native 0.87，2026-08-11</a>）与 <strong>0.87.1 官方 npm 源码包</strong>交叉核对写成：公告里的每一项，都尽量给出源码中的落点。</p></blockquote><h2 id="一、版本全景" tabindex="-1">一、版本全景 <a class="header-anchor" href="#一、版本全景" aria-label="Permalink to &quot;一、版本全景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>首发版本</td><td>0.87.0（2026-08-11）</td></tr><tr><td>本教程锚点</td><td><strong>0.87.1</strong>（0.87 稳定线上的补丁版本，以 bugfix 为主）</td></tr><tr><td>贡献规模</td><td>265 个提交、74 位贡献者</td></tr><tr><td>React peer</td><td><code>^19.2.3</code>（源码 <code>package.json</code> peerDependencies）</td></tr><tr><td>Node 引擎</td><td><code>^22.13.0 || ^24.3.0 || &gt;= 26.0.0</code></td></tr><tr><td>支持窗口变化</td><td>0.84.x 随 0.87 发布转入 <strong>unsupported</strong></td></tr></tbody></table><blockquote><p>怎么读 0.87.0 与 0.87.1 的关系：0.87.0 引入全部特性与破坏性变更；0.87.1 是同一稳定线上的修复版。<strong>新项目直接用 0.87.1 即可，特性清单以 0.87.0 公告为准</strong>；补丁级的逐项修复见官方 Releases 页。本学院所有源码行号引用均来自 0.87.1 tarball。</p></blockquote><h2 id="二、四大亮点" tabindex="-1">二、四大亮点 <a class="header-anchor" href="#二、四大亮点" aria-label="Permalink to &quot;二、四大亮点&quot;">​</a></h2><h3 id="_2-1-strict-typescript-api-默认启用" tabindex="-1">2.1 Strict TypeScript API 默认启用 <a class="header-anchor" href="#_2-1-strict-typescript-api-默认启用" aria-label="Permalink to &quot;2.1 Strict TypeScript API 默认启用&quot;">​</a></h3><p>0.80 起作为预览的 Strict API，在 0.87 成为<strong>默认</strong> JS API：</p><ul><li>类型不再手写维护，而是<strong>从 RN 源码直接生成</strong>（源码包 <code>types_generated/</code> 目录 + <code>package.json</code> 的 <code>exports[&quot;.&quot;].types: &quot;./types_generated/index.d.ts&quot;</code> 即为证据），消除了长期存在的&quot;类型与实现漂移&quot;；</li><li>公共 API 被严格限定为 <code>react-native</code> <strong>根出口</strong>——<code>react-native/Libraries/*</code> 深度导入现在是类型错误；</li><li>ref 有了专用类型：<code>ViewInstance</code>、<code>TextInputInstance</code> 等；</li><li>临时逃生舱：tsconfig 加 <code>&quot;customConditions&quot;: [&quot;react-native&quot;, &quot;react-native-legacy-deep-imports&quot;]</code> 可回退旧类型，<strong>仅保留到 0.88</strong>。源码 <code>package.json</code> 的 exports 中可以看到这个 condition 的实际挂载点。</li></ul><h3 id="_2-2-metro-0-84-→-0-87-更快、更瘦" tabindex="-1">2.2 Metro 0.84 → 0.87：更快、更瘦 <a class="header-anchor" href="#_2-2-metro-0-84-→-0-87-更快、更瘦" aria-label="Permalink to &quot;2.2 Metro 0.84 → 0.87：更快、更瘦&quot;">​</a></h3><ul><li>source map 生成速度 <strong>2 倍</strong>（RN DevTools 加载明显更快）；</li><li>source map 存储优化，Metro <strong>内存占用减半</strong>；</li><li>正式支持 TypeScript / ESM 配置文件（如 <code>metro.config.mts</code>）；</li><li>移除 YAML 配置与 <code>.es6</code> 扩展名配置支持；</li><li>解析器新特性：package self-resolve（包可引用自己的 exports）。</li></ul><h3 id="_2-3-ios-实验性支持-swift-package-manager-swiftpm" tabindex="-1">2.3 iOS 实验性支持 Swift Package Manager（SwiftPM） <a class="header-anchor" href="#_2-3-ios-实验性支持-swift-package-manager-swiftpm" aria-label="Permalink to &quot;2.3 iOS 实验性支持 Swift Package Manager（SwiftPM）&quot;">​</a></h3><p>CocoaPods 近十年的统治地位首次迎来官方替代路径（<strong>opt-in，CocoaPods 仍是默认与受支持路径</strong>）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ios</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react-native</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> spm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deintegrate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 移除 CocoaPods，把 Swift package 引用注入现有 .xcodeproj</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li>只需 Xcode，不再需要 Ruby / Bundler / CocoaPods；签名、capabilities、build phases 原样保留；</li><li>依赖变更后<strong>不用再手动跑安装命令</strong>，构建时自动重新 autolinking（新 clone / CI 需先跑一次 <code>npx react-native spm</code>）；</li><li>社区库若没有 <code>Package.swift</code>，可用 <code>npx react-native spm scaffold</code> 从 podspec 生成；</li><li>官方明确标注：<strong>命令与生成物布局可能变，暂勿用于生产</strong>（RFC #0994）。</li></ul><p><strong>配套的头文件破坏性变更</strong>：新增 <code>ReactNativeHeaders.xcframework</code> 与 <code>ReactNativeDependenciesHeaders.xcframework</code>，裸角度导入必须补命名空间：</p><div class="language-objc vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">objc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #import </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RCTAppDelegate.h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #import </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">React</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RCTAppDelegate.h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_2-4-android-gradle-plugin-agp-9" tabindex="-1">2.4 Android Gradle Plugin（AGP）9 <a class="header-anchor" href="#_2-4-android-gradle-plugin-agp-9" aria-label="Permalink to &quot;2.4 Android Gradle Plugin（AGP）9&quot;">​</a></h3><p>首个支持 AGP 9 的 RN 版本。源码 <code>gradle/libs.versions.toml</code> 中的实际锚点：<code>agp = &quot;9.2.1&quot;</code>、<code>kotlin = &quot;2.2.0&quot;</code>。</p><p>官方当前建议在 <code>android/gradle.properties</code> 关闭 AGP 9 的两个新行为（AGP 10 起这两个开关会被移除）：</p><div class="language-properties vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 暂不启用 AGP 9 内置 Kotlin 与新 DSL</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">android.builtInKotlin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">android.newDsl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=false</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="三、破坏性变更清单-breaking-changes" tabindex="-1">三、破坏性变更清单（Breaking Changes） <a class="header-anchor" href="#三、破坏性变更清单-breaking-changes" aria-label="Permalink to &quot;三、破坏性变更清单（Breaking Changes）&quot;">​</a></h2><h3 id="_3-1-工具链门槛" tabindex="-1">3.1 工具链门槛 <a class="header-anchor" href="#_3-1-工具链门槛" aria-label="Permalink to &quot;3.1 工具链门槛&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>新要求</th><th>源码锚点（gradle/libs.versions.toml）</th></tr></thead><tbody><tr><td>Node.js</td><td>≥ 22.13.0</td><td>package.json <code>engines.node</code></td></tr><tr><td>Kotlin</td><td>最低 2.0（内置 2.2.0）</td><td><code>kotlin = &quot;2.2.0&quot;</code></td></tr><tr><td>minCompileSdk</td><td>34（库必须 compileSdk ≥ 34）</td><td>公告</td></tr><tr><td>compileSdk / buildTools</td><td><strong>37 / 37.0.0</strong></td><td><code>compileSdk = &quot;37&quot;</code>、<code>buildTools = &quot;37.0.0&quot;</code></td></tr><tr><td>NDK</td><td>27.1.12297006</td><td><code>ndkVersion = &quot;27.1.12297006&quot;</code></td></tr><tr><td>minSdk（应用）</td><td>24</td><td><code>minSdk = &quot;24&quot;</code></td></tr></tbody></table><h3 id="_3-2-js-ts-api-移除与收紧" tabindex="-1">3.2 JS/TS API 移除与收紧 <a class="header-anchor" href="#_3-2-js-ts-api-移除与收紧" aria-label="Permalink to &quot;3.2 JS/TS API 移除与收紧&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变更</th><th>替代方案</th></tr></thead><tbody><tr><td><code>react-native/Libraries/*</code> 深度导入</td><td>一律改根出口导入（Strict API）</td></tr><tr><td><code>src/private/*</code> 深度导入</td><td><strong>直接移除</strong>，无逃生舱</td></tr><tr><td><code>*Properties</code> 类型别名（如 <code>ViewProperties</code>）</td><td>用 <code>*Props</code>（如 <code>ViewProps</code>）</td></tr><tr><td><code>InteractionManager</code></td><td><strong>移除</strong>，用 <code>requestIdleCallback</code></td></tr><tr><td><code>Modal</code> 的 <code>animated</code> prop</td><td>移除（动画行为已内置）</td></tr><tr><td><code>StatusBar</code> 的 <code>backgroundColor</code> / <code>translucent</code> / <code>networkActivityIndicatorVisible</code> 及对应 setter</td><td>移除（平台原生行为接管）</td></tr><tr><td><code>ScrollView</code> 的 <code>keyboardShouldPersistTaps</code> 布尔值</td><td>只接受 <code>&#39;never&#39; | &#39;always&#39; | &#39;handled&#39;</code> 字符串</td></tr><tr><td><code>useTurboModules</code> feature flag</td><td>移除（TurboModules 永远开启）</td></tr><tr><td><code>useColorScheme()</code> 返回 <code>&#39;unspecified&#39;</code></td><td>现在返回 <code>ColorSchemeName | null</code>，未指定时是 <code>null</code></td></tr><tr><td><code>NativeDialogManagerAndroid</code> 导出</td><td>移除</td></tr><tr><td>根出口的（未公开的）<code>Touchable</code></td><td>移除，需要时自行扩展 <code>ViewProps</code></td></tr><tr><td><code>NativeMethods</code> / <code>NativeMethodsMixin</code> 类型</td><td>用 <code>HostInstance</code></td></tr><tr><td>YAML Metro 配置 / <code>.es6</code> 配置文件</td><td>改为 <code>metro.config.js</code>/<code>.mts</code></td></tr></tbody></table><h3 id="_3-3-包与工具链" tabindex="-1">3.3 包与工具链 <a class="header-anchor" href="#_3-3-包与工具链" aria-label="Permalink to &quot;3.3 包与工具链&quot;">​</a></h3><ul><li><code>@react-native/core-cli-utils</code> 不再发布（仓库内仍保留参考实现）；</li><li><code>react-native/rn-get-polyfills</code> 移除 → 用 <code>@react-native/js-polyfills</code>；</li><li><code>@react-native/jest-preset</code> 必须作为独立包消费；</li><li>不再支持通过 WebSocket 连接独立 <code>react-devtools</code> 包 → 统一用 <strong>React Native DevTools</strong>（教程 06 章）。</li></ul><h2 id="四、弃用预告-deprecations-未来版本移除" tabindex="-1">四、弃用预告（Deprecations，未来版本移除） <a class="header-anchor" href="#四、弃用预告-deprecations-未来版本移除" aria-label="Permalink to &quot;四、弃用预告（Deprecations，未来版本移除）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>弃用项</th><th>推荐替代</th></tr></thead><tbody><tr><td><code>react-native/Libraries/Core/InitializeCore</code></td><td><code>react-native/setup-env</code>（源码 exports 中已有 <code>&quot;./setup-env&quot;: &quot;./src/setup-env.js&quot;</code>）</td></tr><tr><td><code>@react-native/assets-registry</code></td><td>根出口 <code>AssetRegistry</code> + <code>@react-native/asset-utils</code></td></tr><tr><td><code>ImageBackground</code></td><td><code>View</code> + 绝对定位 <code>Image</code> 自行组合</td></tr><tr><td><code>NativeMethods</code> 接口</td><td><code>HostInstance</code></td></tr><tr><td><code>Appearance.setColorScheme(&#39;unspecified&#39;)</code></td><td><code>&#39;auto&#39;</code></td></tr><tr><td>Android：<code>DrawerLayoutAndroid</code></td><td><code>react-native-drawer-layout</code></td></tr><tr><td>Android：<code>UIBlock</code> / <code>UIManagerModule.addUIBlock</code> / <code>prependUIBlock</code></td><td><code>UIManagerListener</code> 或 View Commands</td></tr><tr><td>Android：<code>DefaultReactActivityDelegate</code> 的新架构 flag 构造参数</td><td>新架构是唯一架构，flag 无意义</td></tr><tr><td>iOS：<code>TimingModule</code></td><td>新动画时序路径</td></tr><tr><td>iOS：<code>RCTTurboModuleEnabled()</code> / <code>RCTEnableTurboModule()</code></td><td>TurboModule 永远开启</td></tr></tbody></table><h2 id="五、与漫画篇的呼应-源码里看这些变更" tabindex="-1">五、与漫画篇的呼应（源码里看这些变更） <a class="header-anchor" href="#五、与漫画篇的呼应-源码里看这些变更" aria-label="Permalink to &quot;五、与漫画篇的呼应（源码里看这些变更）&quot;">​</a></h2><p>读到这里，Part I 的源码分析恰好为公告做了&quot;现场直播&quot;：</p><ul><li><strong>InitializeCore 瘦身为壳</strong>（弃用项 #1）→ 漫画 <a href="./../comics/06-js-core">06 章</a>：<code>InitializeCore.js:L13-37 → setup-env.js:L14-22</code>；</li><li><strong>TurboModules 永远开启、flag 移除</strong> → 漫画 <a href="./../comics/04-turbo-modules-codegen">04 章</a>：ModuleHolder 懒创建已是唯一路径；</li><li><strong>旧桥 API 全面退场</strong> → 漫画 <a href="./../comics/08-ios">08 章</a>：<code>RCTBridge.h:L96-124</code> 构造 API 标 deprecated、bridgeless 默认；</li><li><strong>Strict API 根出口契约</strong> → 漫画 01 章的三层世界：<code>index.js</code> 懒 getter 出口就是公共 API 的物理边界。</li></ul><h2 id="六、0-87-1-补丁版说明" tabindex="-1">六、0.87.1 补丁版说明 <a class="header-anchor" href="#六、0-87-1-补丁版说明" aria-label="Permalink to &quot;六、0.87.1 补丁版说明&quot;">​</a></h2><p>0.87.1 不引入新特性，遵循 semver 补丁约定：修复 0.87.0 后的稳定性问题。本教程组件篇给出的三方库版本组合（如 Reanimated <strong>4.7.0</strong> + react-native-worklets <strong>0.13.0</strong>，旧版 Reanimated 3.19.5 与 0.87 工具链编译不兼容）均已在 0.87.1 上验证。具体补丁条目以官方 GitHub Releases 为准。</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>Q1：0.84 项目还能收到安全修复吗？</strong> 不能。0.87 发布后 0.84.x 转入 unsupported。建议至少升到 0.86（无用户侧破坏性变更的过渡版本）再冲 0.87。</p><p><strong>Q2：Strict API 只影响类型，运行时不受影响吧？</strong> 对。它是纯 TypeScript 分析层变化，按 tsconfig 作用域生效，App 与三方库可以独立迁移，不影响线上 bundle。</p><p><strong>Q3：必须现在就切 SwiftPM 吗？</strong> 完全不用。SwiftPM 是实验特性，CocoaPods 是默认且受支持路径，生产项目继续用 Podfile。</p><hr><blockquote><p>下一章：<a href="./08-migration">08 · 迁移指南</a>——从旧版本一步步升到 0.87.1。</p></blockquote>`,41)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
